-- Family Friendly / Scout Fox -- PostgreSQL schema.
--
-- Supersedes the loose CREATE TABLE sketch in the repository-root
-- `Uberliketasks` file: the four tables from that sketch are kept with the
-- same names and columns, and the tables the running application actually
-- needs (activities, users, points_ledger) are added alongside them.
--
--   psql "$DATABASE_URL" -f db/schema.sql
--   psql "$DATABASE_URL" -f db/seed.sql      -- generated by scripts/seed_db.py
--
-- Keep this file in sync with db/schema.sqlite.sql; tests/test_seed_data.py
-- asserts that both declare the same tables and columns.

DROP TABLE IF EXISTS points_ledger;
DROP TABLE IF EXISTS feedback;
DROP TABLE IF EXISTS trips;
DROP TABLE IF EXISTS users;
DROP TABLE IF EXISTS families;
DROP TABLE IF EXISTS global_patterns;
DROP TABLE IF EXISTS activities;

-- Family-friendly places served by GET /recommend.
CREATE TABLE activities (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  type TEXT NOT NULL,
  category TEXT NOT NULL,
  city TEXT NOT NULL,
  state TEXT NOT NULL,
  indoor_or_outdoor TEXT NOT NULL CHECK (indoor_or_outdoor IN ('indoor', 'outdoor')),
  price_tier TEXT NOT NULL CHECK (price_tier IN ('free', '$', '$$', '$$$')),
  min_age INT NOT NULL,
  max_age INT NOT NULL,
  avg_duration_hours REAL NOT NULL,
  rating REAL NOT NULL CHECK (rating >= 0 AND rating <= 5),
  tags JSONB NOT NULL,
  description TEXT NOT NULL,
  CHECK (min_age <= max_age)
);

CREATE INDEX activities_state_idx ON activities (state);
CREATE INDEX activities_state_indoor_idx ON activities (state, indoor_or_outdoor);
CREATE INDEX activities_category_idx ON activities (category);

CREATE TABLE families (
  family_id INT PRIMARY KEY,
  name TEXT NOT NULL,
  members JSONB NOT NULL,            -- ages, preferences
  budget_range TEXT,
  home_location TEXT
);

-- API-key holders. Mirrors USER_TIERS in api/auth_tiers.py.
CREATE TABLE users (
  api_key TEXT PRIMARY KEY,
  display_name TEXT NOT NULL,
  email TEXT,
  tier TEXT NOT NULL CHECK (tier IN ('free', 'pro', 'business')),
  points INT NOT NULL DEFAULT 0 CHECK (points >= 0),
  home_state TEXT,
  family_id INT REFERENCES families(family_id)
);

CREATE TABLE trips (
  trip_id INT PRIMARY KEY,
  family_id INT REFERENCES families(family_id),
  destination TEXT,
  start_date DATE,
  end_date DATE,
  itinerary JSONB
);

CREATE INDEX trips_family_idx ON trips (family_id);

CREATE TABLE feedback (
  feedback_id INT PRIMARY KEY,
  trip_id INT REFERENCES trips(trip_id),
  family_id INT REFERENCES families(family_id),
  rating INT CHECK (rating >= 1 AND rating <= 5),
  comments TEXT
);

CREATE INDEX feedback_trip_idx ON feedback (trip_id);

CREATE TABLE global_patterns (
  pattern_id INT PRIMARY KEY,
  cluster_name TEXT,
  top_destinations JSONB,
  seasonal_preferences JSONB,
  notes TEXT
);

-- Append-only points history behind /points/points_history and /points/leaderboard.
CREATE TABLE points_ledger (
  entry_id INT PRIMARY KEY,
  api_key TEXT REFERENCES users(api_key),
  event TEXT NOT NULL,
  points INT NOT NULL,
  activity_id TEXT REFERENCES activities(id),
  created_at DATE,
  note TEXT
);

CREATE INDEX points_ledger_api_key_idx ON points_ledger (api_key);
